    input  wire        clk,
    input  wire        rst_n,
    input  wire        valid_i,
    input  wire [31:0] a_i,
    input  wire [31:0] b_i,
    output reg         valid_o,
    output reg  [31:0] y_o
);

    wire [31:0] gv [0:5];
    wire [31:0] pv [0:5];

    assign gv[0] = a_i & b_i;
    assign pv[0] = a_i ^ b_i;

    genvar l, i;
    generate
      for (l = 0; l < 5; l = l + 1) begin : lev
        for (i = 0; i < 32; i = i + 1) begin : bt
          if (i >= (1 << l)) begin : mg
            assign gv[l+1][i] = gv[l][i] | (pv[l][i] & gv[l][i-(1<<l)]);
            assign pv[l+1][i] = pv[l][i] & pv[l][i-(1<<l)];
